from pathlib import Path
import re
p=Path('index.html'); h=p.read_text(encoding='utf-8')

def sec(sid,new):
 global h
 pat=re.compile(r'<section\b(?=[^>]*\bid=["\']'+re.escape(sid)+r'["\'])[^>]*>.*?</section>',re.S|re.I)
 if len(pat.findall(h))!=1: raise SystemExit(f'{sid} section mismatch')
 h=pat.sub(new,h,count=1)

h=h.replace('Nordic Viking Heritage — Viking Voyage II, Day 23. Chapter III: Newfoundland to Nova Scotia.','Nordic Viking Heritage — Viking Voyage II, Day 24. Chapter III: Newfoundland to Nova Scotia.').replace('<title>Nordic Viking Heritage — Viking Voyage II — Day 23</title>','<title>Nordic Viking Heritage — Viking Voyage II — Day 24</title>').replace('href="#history-day-20">HISTORY</a>','href="#history-day-24">HISTORY</a>').replace('href="#our-saga-day-21">SAGA</a>','href="#our-saga-day-24">SAGA</a>')

sec('voyage','''<section class="status parchment" id="voyage"><div class="wrap"><div class="status-head"><div><div class="kicker red">THE SHIP'S LOG — DAY 24</div><h1>ONE FLEET. ONE SAGA. ONE HORIZON.</h1><p>The fleet continues south across the open sea through Chapter III toward Nova Scotia.</p></div><img class="seal" src="assets/one-crew-one-saga.png" alt="One Crew, One Saga"></div><div class="stats"><article><strong>99</strong><small>SAILORS ABOARD</small><em>One crew</em></article><article><strong>44,469,539</strong><small>TOTAL STEPS</small><em>Steps toward Florida</em></article><article><strong>≈ 28,905.2 KM</strong><small>DISTANCE COVERED</small><em>At 0.65 m per step</em></article><article><strong>59.29%</strong><small>OF OUR GOAL</small><em>75,000,000 steps</em></article></div></div></section>''')

sec('dispatch','''<section class="dark-section" id="dispatch"><div class="wrap"><div class="copy"><div class="kicker gold">⚔️ VIKING DISPATCH — DAY 24 ⚔️</div><p>The fleet continues south across the open sea.</p><p>No coast has appeared. No answer has risen beyond the horizon.</p><p>Yet today, another Viking stepped aboard.</p><p>99 Vikings now pull together beneath the same red-and-white sails. During the last day, the fleet advanced another 1,844,344 steps — carrying us deeper into Chapter III and closer to Nova Scotia.</p><p><strong>44,469,539 steps<br>≈ 28,905.2 km<br>59.29% completed</strong></p><p>Þóra’s warning remains with Captain Hákon.</p><p>Hugin watches the southern horizon. Munin remains beside Þóra.</p><p>The sea gives nothing away.</p><p>But the fleet does not turn back.</p><p><strong>ONE FLEET. ONE SAGA. ONE HORIZON.</strong></p><p><strong>ROW ON. ⚔️</strong></p><figure class="framed"><img class="zoomable" src="day-24-viking-dispatch.jpg" alt="Viking Dispatch Day 24"><figcaption>VIKING DISPATCH — DAY 24</figcaption></figure></div></div></section>''')

sec('voyage-map','''<section class="map-section" id="voyage-map"><div class="wrap"><div class="kicker gold">THE VOYAGE MAP — CHAPTER III</div><h2>NEWFOUNDLAND → NOVA SCOTIA</h2><p class="intro">The fleet continues south through Chapter III. Day 24 brings the voyage to <strong>44,469,539 steps</strong> — approximately <strong>28,905.2 km</strong> since Greenland.</p><div class="tags"><span>DAY 24</span><span>99 SAILORS</span><span>44,469,539 STEPS</span><span>≈ 28,905.2 KM</span><span>59.29% COMPLETE</span></div><figure class="framed"><img class="zoomable" src="day-24-voyage-map.jpg" alt="Viking Voyage II Day 24 map — Newfoundland to Nova Scotia"><figcaption>THE VOYAGE MAP — DAY 24 · CHAPTER III</figcaption></figure></div></section>''')

sec('saga','''<section class="layers parchment" id="saga"><div class="wrap"><div class="kicker red">THREE LAYERS — ONE EXPERIENCE</div><h2>THE VOYAGE BECOMES A LIVING SAGA</h2><div class="layer-grid"><a class="layer-link" href="#history-day-24"><article><span>01</span><h3>HISTORY</h3><p>Verified history and archaeology — including the small realities of everyday Viking life.</p></article></a><a class="layer-link" href="#myth-day-24"><article><span>02</span><h3>MYTH &amp; SAGA</h3><p>The gods, ravens and stories of the Norse world give the voyage its mythic voice.</p></article></a><a class="layer-link" href="#our-saga-day-24"><article><span>03</span><h3>OUR SAGA</h3><p>The crew's real steps shape the living story we create together.</p></article></a></div></div></section>''')

sec('our-saga-day-21','''<section class="dark-section" id="our-saga-day-24"><div class="wrap"><div class="copy"><div class="kicker gold">⚔️ OUR SAGA — DAY 24 ⚔️</div><p>As the last light faded, a place was made for another Viking among the fleet.</p><p>At sea, a welcome is not carried by words alone.</p><p>It is heard when another voice joins the call, when another hand strengthens the crew, and when 99 Vikings choose the same horizon.</p><p>At the bow, Þóra watched the southern mist.</p><p>Munin remained beside her.</p><p>Above the fleet, Hugin flew ahead until he became little more than a dark shape against the fading light.</p><p>Captain Hákon held the course.</p><p>No one aboard knew what waited beyond the horizon.</p><p>That was why their choice mattered.</p><p>They continued together.</p><p>Our saga is not written by one captain, one ship, or one great deed.</p><p>It is written by every Viking who keeps the fleet moving when the sea gives no answer.</p><p><strong>ONE FLEET. ONE SAGA. ONE HORIZON.</strong></p><p><strong>ROW ON. ⚔️</strong></p><figure class="framed"><img class="zoomable" src="day-24-our-saga.jpg" alt="Our Saga Day 24"><figcaption>OUR SAGA — DAY 24</figcaption></figure></div></div></section>''')

sec('history-day-20','''<section class="dark-section" id="history-day-24"><div class="wrap"><div class="copy"><div class="kicker gold">⚔️ HISTORY — DAY 24 ⚔️</div><h2>FINDING A COURSE WITHOUT A MODERN COMPASS</h2><p>Norse sailors crossed open stretches of the North Atlantic without modern charts or navigation instruments.</p><p>They could observe the sun and stars when visible, judge wind and waves, and rely on remembered routes and knowledge passed between experienced crews.</p><p>Researchers have also tested reconstructions of a possible “sun compass” that uses a shadow to help indicate direction. Such a device could work — but there is no secure evidence that Viking Age sailors used it routinely.</p><p>What is certain is that these voyages required seaworthy ships, close observation, and generations of practical knowledge.</p><p>Our fleet follows a map south.</p><p>They followed the sky, the sea, and experience.</p><p><strong>THE SAGA MAY BE WILD.<br>HISTORY MUST BE TRUE. ⚔️</strong></p><figure class="framed"><img class="zoomable" src="day-24-history.jpg" alt="History Day 24 — Finding a course without a modern compass"><figcaption>HISTORY — DAY 24</figcaption></figure></div></div></section>''')

sec('myth-day-20','''<section class="parchment" id="myth-day-24"><div class="wrap"><div class="copy"><div class="kicker red">🌙 MYTH &amp; SAGA — DAY 24 🌙</div><h2>THE CHASE ABOVE</h2><p>The moon crossed the night sky.</p><p>Behind it, something ran where no ship could ever sail.</p><p>In Snorri’s telling, Máni guides the moon across the heavens while the wolf Hati pursues him through the darkness.</p><p>Night after night, the chase continues.</p><p>Máni does not abandon his course.</p><p>Hati does not cease his pursuit.</p><p>Far below, 99 Vikings sailed south across the open sea.</p><p>They were not part of the ancient chase.</p><p>But beneath that same restless sky, they understood its lesson:</p><p>The path ahead does not need to be visible for the journey to continue.</p><p>Some journeys are chosen.</p><p>Others never end.</p><p><strong>THE MOON MOVES.<br>THE WOLF FOLLOWS.<br>THE FLEET SAILS ON.</strong></p><p><strong>ROW ON. ⚔️</strong></p><figure class="framed"><img class="zoomable" src="day-24-myth-and-saga.jpg" alt="Myth and Saga Day 24 — The Chase Above"><figcaption>MYTH &amp; SAGA — DAY 24 · THE CHASE ABOVE</figcaption></figure></div></div></section>''')

roll='<article><span>ROBEDSON</span><strong>Birger</strong><small class="old-norse">Birgir</small><small class="runes">ᛒᛁᚱᚴᛁᛦ</small></article>'
add=roll+'<article><span>Robert Drope</span><strong>Eyvind</strong><small class="old-norse">Eyvindr</small><small class="runes">ᛅᚢᛁᚾᛏᛦ</small></article><article><span>Khalil Saudi Arabia</span><strong>Hjalti</strong><small class="old-norse">Hjalti</small><small class="runes">ᚼᛁᛅᛚᛏᛁ</small></article><article><span>Litus</span><strong>Dag</strong><small class="old-norse">Dagr</small><small class="runes">ᛏᛅᚴᛦ</small></article>'
if h.count(roll)!=1: raise SystemExit('roll anchor mismatch')
h=h.replace(roll,add,1)

sec('honors','''<section class="parchment honors" id="honors"><div class="wrap"><div class="kicker red">CREW HONORS — DAY 24</div><h2>THREE NAMES ENTER THE SHIP'S ROLL</h2><div class="honors-explainer"><div class="kicker red">THE HONOR BEHIND THE NAME</div><h3>EVERY OAR MATTERS</h3><p>Crew Honors belongs to <strong>OUR SAGA</strong>. It is a Viking Voyage II tradition, not a claimed reconstruction of a documented Viking Age ceremony.</p><p>Once entered into <strong>THE SHIP'S ROLL</strong>, a sailor's name remains part of this voyage.</p></div><figure class="framed"><img class="zoomable" src="day-24-crew-honors.jpg" alt="Crew Honors Day 24 — Eyvind, Hjalti and Dag"><figcaption>CREW HONORS — DAY 24 · EYVIND · HJALTI · DAG</figcaption></figure><div class="naming-list"><article><span>Robert Drope</span><strong>EYVIND <em>(Eyvindr)</em></strong><small>ᛅᚢᛁᚾᛏᛦ</small></article><article><span>Khalil Saudi Arabia</span><strong>HJALTI <em>(Hjalti)</em></strong><small>ᚼᛁᛅᛚᛏᛁ</small></article><article><span>Litus</span><strong>DAG <em>(Dagr)</em></strong><small>ᛏᛅᚴᛦ</small></article></div></div></section>''')

m='<div class="crew-honors-archive-grid">'; card='<figure><img class="zoomable" src="day-24-crew-honors.jpg" alt="Day 24 Crew Honors"><figcaption>DAY 24 · EYVIND · HJALTI · DAG</figcaption></figure>'
